indexStyle:
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeSlideRight {
  from { opacity: 0; transform: translateX(-20px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes shimmer {
  0% { background-position: -200% center; }
  100% { background-position: 200% center; }
}
@keyframes breathe {
  0%, 100% { box-shadow: 0 0 0 0 rgba(255,107,53,0.3); }
  50% { box-shadow: 0 0 0 8px rgba(255,107,53,0); }
}

body {
  font-family: 'Noto Serif SC', Georgia, 'Times New Roman', serif !important;
  line-height: 1.8 !important;
  color: #24292f !important;
  background-color: #fafaf8 !important;
  max-width: 960px !important;
}

[data-color-mode="dark"] body {
  color: #e6edf3 !important;
  background-color: #0d1117 !important;
}

#header {
  border-bottom: 2px solid #ff6b35 !important;
  padding-bottom: 12px !important;
  margin-bottom: 24px !important;
  animation: fadeSlideIn 0.6s ease both;
}

.avatar {
  transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
  border: 2px solid #ff6b35 !important;
  animation: breathe 3s ease-in-out infinite;
}
.avatar:hover {
  transform: scale(1.15) rotate(6deg) !important;
}

.title-left a {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif !important;
  letter-spacing: 1px !important;
  font-size: 32px !important;
  background: linear-gradient(90deg, #ff6b35, #e84526, #ff6b35) !important;
  background-size: 200% auto !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  animation: shimmer 4s linear infinite;
}

#content > div:first-child {
  font-family: 'Noto Serif SC', Georgia, serif !important;
  font-style: italic !important;
  color: #656d76 !important;
  font-size: 15px !important;
  margin-bottom: 20px !important;
  padding: 6px 14px !important;
  border-left: 3px solid #ff6b35 !important;
  background: #fff4ef !important;
  border-radius: 0 8px 8px 0 !important;
  animation: fadeSlideRight 0.8s ease 0.2s both;
}

[data-color-mode="dark"] #content > div:first-child {
  color: #8b949e !important;
  background: #2a1f1a !important;
}

.SideNav {
  border-radius: 8px !important;
  overflow: hidden !important;
}

.SideNav-item {
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) !important;
  padding: 14px 16px !important;
  border-left: 3px solid transparent !important;
}
.SideNav-item:hover {
  background-color: #fff4ef !important;
  border-left-color: #ff6b35 !important;
  transform: translateX(6px);
}

[data-color-mode="dark"] .SideNav-item:hover {
  background-color: #2a1f1a !important;
}

.listTitle {
  font-family: 'Noto Serif SC', Georgia, serif !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  transition: color 0.2s;
}
.SideNav-item:hover .listTitle {
  color: #ff6b35 !important;
}

.Label {
  border-radius: 20px !important;
  padding: 2px 10px !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  transition: transform 0.2s;
}
.Label:hover {
  transform: scale(1.08);
}

.LabelTime {
  opacity: 0.8;
}

#footer {
  border-top: 1px solid #d8dee4 !important;
  padding-top: 20px !important;
  color: #656d76 !important;
  animation: fadeSlideIn 0.6s ease 0.4s both;
}
#footer a {
  color: #ff6b35 !important;
  text-decoration: none !important;
}
#footer a:hover {
  opacity: 0.7;
}

[data-color-mode="dark"] #footer {
  border-top-color: #30363d !important;
  color: #8b949e !important;
}

.title-right a, .title-right button {
  transition: transform 0.3s, color 0.3s !important;
}
.title-right a:hover, .title-right button:hover {
  transform: scale(1.15) !important;
  color: #ff6b35 !important;
}

@media (max-width: 600px) {
  body { padding: 12px !important; }
  .title-left a { font-size: 24px !important; }
  .SideNav-item { padding: 10px 12px !important; }
}

::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #d8dee4; border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #656d76; }

