document.addEventListener('DOMContentLoaded', function() {
  var items = document.querySelectorAll('.SideNav-item');
  items.forEach(function(item, i) {
    item.style.opacity = '0';
    item.style.transform = 'translateY(20px)';
    item.style.transition = 'opacity 0.5s ease, transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1)';
    setTimeout(function() {
      item.style.opacity = '1';
      item.style.transform = 'translateY(0)';
    }, 100 + 120 * i);
  });
});

script:
(function() {
  var btn = document.createElement('button');
  btn.innerHTML = '\u2191';
  btn.setAttribute('title', '\u56DE\u5230\u9876\u90E8');
  btn.style.cssText = 'position:fixed;bottom:32px;right:32px;width:46px;height:46px;border-radius:50%;background:linear-gradient(135deg,#ff6b35,#e84526);color:#fff;border:none;font-size:20px;cursor:pointer;opacity:0;transform:translateY(20px);transition:opacity 0.4s,transform 0.4s;z-index:999;box-shadow:0 4px 14px rgba(255,107,53,0.35);';
  document.body.appendChild(btn);
  window.addEventListener('scroll', function() {
    if (window.scrollY > 300) {
      btn.style.opacity = '1';
      btn.style.transform = 'translateY(0)';
    } else {
      btn.style.opacity = '0';
      btn.style.transform = 'translateY(20px)';
    }
  });
  btn.addEventListener('click', function() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
  btn.addEventListener('mouseenter', function() {
    btn.style.transform = 'translateY(-3px) scale(1.1)';
    btn.style.boxShadow = '0 6px 20px rgba(255,107,53,0.5)';
  });
  btn.addEventListener('mouseleave', function() {
    btn.style.transform = 'translateY(0)';
    btn.style.boxShadow = '0 4px 14px rgba(255,107,53,0.35)';
  });
})();
